import{_ as e,o as d,c as a,ag as o}from"./chunks/framework.C5oN-8Wt.js";const m=JSON.parse('{"title":"向量点表源","description":"","frontmatter":{},"headers":[],"relativePath":"v0.2.0-alpha/modules/vector_source/index.md","filePath":"v0.2.0-alpha/modules/vector_source/index.md"}'),r={name:"v0.2.0-alpha/modules/vector_source/index.md"};function i(c,t,n,l,h,s){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="向量点表源" tabindex="-1">向量点表源 <a class="header-anchor" href="#向量点表源" aria-label="Permalink to &quot;向量点表源&quot;">​</a></h1><p>适用：v0.2.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>vector_source</code> · 模块定义版本：6</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>按给定点表循环输出数据，可构造容易逐项核对的序列、整数向量或离散码元。一个 item 可以包含多个连续分量，适合学习数据形状与流标签的位置。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>向量点表源.out → 匹配类型与长度的增益器.in → 延时器.in</code>。观察向量时，在变量选择中明确选择分量下标；未打包码元模式可接符号映射器。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输出</td><td><code>out</code>（输出）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>点表按 item 内分量连续排列：长度为 4 时，前四个值组成第一个 item，后四个值组成第二个。数据实部和虚部列表等长，总元素数必须整除向量长度；非复数数据的虚部都为零。采样率按 item/s 计。</p><p>码元索引模式只使用标量 item，值须落在 M 个编号内。流标签的 offset 是一个循环点表内的 item 偏移十进制字符串，不能填分量偏移；整数标签也按指定值类型保存。特殊点表更新标签用于显式码元源，并须与下游映射表大小一致。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>采样率 (Hz)<br><code>sample_rate_hz</code></td><td><code>4096</code></td><td>范围 1 至 1000000；Master 支持 1–1000000 Hz，可输入小数；下限保证单个采样周期不超过 1 秒。</td><td>重新准备</td></tr><tr><td>数据实部（item 内分量连续排列）<br><code>data_real</code></td><td><code>[1]</code></td><td>按字段类型填写，见下文说明</td><td>重新准备</td></tr><tr><td>数据虚部<br><code>data_imag</code></td><td><code>[0]</code></td><td>按字段类型填写，见下文说明</td><td>重新准备</td></tr><tr><td>每个 item 的向量长度<br><code>vlen</code></td><td><code>1</code></td><td>范围 1 至 1024；Master 当前容量限制为 1–1024；采样率按 item 计。</td><td>重新准备</td></tr><tr><td>元素类型<br><code>element_type</code></td><td><code>numeric_f64</code></td><td>实数 float32 (<code>numeric_f64</code>)；有符号 int16 (<code>int16</code>)；有符号 int32 (<code>int32</code>)；无符号 byte (<code>byte_u8</code>)；复数 complex64 (<code>complex_f64</code>)；未打包码元索引 (<code>symbol_u8</code>)</td><td>重新准备</td></tr><tr><td>码元索引上界 M<br><code>symbol_count</code></td><td><code>2</code></td><td>范围 1 至 256</td><td>重新准备</td></tr><tr><td>原生流标签（JSON）<br><code>tags</code></td><td><code>[]</code></td><td>offset 是一个循环点表内的 item 偏移字符串；标签保持原生位置和来源。</td><td>重新准备</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>计算参数或结构变化后，先停止，再重新准备和运行。</p><p>点表、类型、向量长度和标签定义改变后重新准备。重开工程会恢复保存的点表与标签定义，并从新运行开始输出；它不会恢复上一次运行进度或重放已投递的独立控制消息。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="int16-向量-item、双端口延时与流标签" tabindex="-1">int16 向量 item、双端口延时与流标签 <a class="header-anchor" href="#int16-向量-item、双端口延时与流标签" aria-label="Permalink to &quot;int16 向量 item、双端口延时与流标签&quot;">​</a></h3><p><a href="../../../downloads/v0.2.0-alpha/vector-items-tags.cnsproj" download>下载 vector-items-tags.cnsproj</a></p><p>来源：PC 本地 GNU Radio 仿真。下载后打开工程，按 F5 运行；本次核验每例参考源运行 2048 item，工程不保存样本。</p><p>int16 向量 item、双端口延时与流标签</p><ul><li>每个 item 有 4 个 int16 分量；1 item 延时移动整组分量。标签 offset=1 表示第 2 个 item，显式选择第 3 分量观察。</li></ul><h3 id="原生消息输入与实际输出" tabindex="-1">原生消息输入与实际输出 <a class="header-anchor" href="#原生消息输入与实际输出" aria-label="Permalink to &quot;原生消息输入与实际输出&quot;">​</a></h3><p><a href="../../../downloads/v0.2.0-alpha/message-control.cnsproj" download>下载 message-control.cnsproj</a></p><p>来源：PC 本地 GNU Radio 仿真。下载后打开工程，按 F5 运行；本次核验每例参考源运行 2048 item，工程不保存样本。</p><p>原生消息输入与实际输出</p><ul><li>普通打开仅运行保存的静态构造图：常量 1、点表与零延时，不自动投递消息。开发验证通过真实运行接口向 dly 投递整数 2、向 cmd 投递 {&quot;ampl&quot;:3,&quot;offset&quot;:2}，核对常量变为 5 及点表延时 2 item。当前属性页尚无消息投递表单。</li></ul><p>当前属性页未提供消息投递表单。运行消息由配套开发验证脚本投递，并在短连续运行中观察实际变化；普通 F5 只运行保存的静态构造图，重开工程不会重放消息。</p><p>向量示例输出四分量 int16 item。明确选第 3 分量（下标 2），比较源、两倍增益与延时结果；延时 1 移动整组分量。标签 offset 为 1，表示循环表的第二个 item，原始标签由配套核验记录检查，波形本身不替代标签位置证据。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>为什么四个数看起来只形成一个时间点？</strong> 它们是同一个 item 的四个分量，共享该 item 的时间。</p><p><strong>普通 byte 能直接接符号映射器吗？</strong> 需使用明确的未打包码元类型并设置索引上界，不能仅因都用一个字节就混用。</p>',32)])])}const u=e(r,[["render",i]]);export{m as __pageData,u as default};
